-- Steadyset schema: profiles, preferences, exercise library, plans, schedule, sessions, sets.
-- All ids are UUIDs generated by the client so that offline retries are idempotent upserts.

create extension if not exists "pgcrypto";

-- ---------------------------------------------------------------- profiles & preferences
create table if not exists public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  display_name text not null default '',
  created_at timestamptz not null default now()
);

create table if not exists public.user_preferences (
  user_id uuid primary key references auth.users (id) on delete cascade,
  theme text not null default 'blush' check (theme in ('blush', 'ember', 'paper', 'graphite')),
  units text not null default 'kg' check (units in ('kg', 'lb')),
  default_rest_seconds integer not null default 90 check (default_rest_seconds between 0 and 900),
  sound_enabled boolean not null default true,
  notifications_enabled boolean not null default false,
  reminders_enabled boolean not null default false,
  reminder_time text not null default '17:30' check (reminder_time ~ '^[0-2][0-9]:[0-5][0-9]$'),
  week_starts_on smallint not null default 1 check (week_starts_on in (0, 1)),
  reduced_motion text not null default 'system' check (reduced_motion in ('system', 'reduce', 'allow')),
  show_missed boolean not null default false,
  tracked_metrics text[] not null default '{}',
  display_name text not null default '',
  default_plan_seeded boolean not null default false,
  updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------- exercise library
-- owner_id null = built-in library (seeded, read-only for users); otherwise a user's custom exercise.
create table if not exists public.exercises (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid references auth.users (id) on delete cascade,
  slug text not null,
  name text not null check (char_length(name) between 1 and 120),
  kind text not null check (kind in ('reps', 'time', 'cardio', 'mobility')),
  primary_muscles text[] not null default '{}',
  secondary_muscles text[] not null default '{}',
  equipment text[] not null default '{}',
  difficulty text not null default 'beginner' check (difficulty in ('beginner', 'intermediate', 'advanced')),
  uses_weight boolean not null default false,
  starting_position text not null default '',
  steps text[] not null default '{}',
  breathing text,
  mistakes text[] not null default '{}',
  safety text[] not null default '{}',
  animation text not null default 'generic',
  created_at timestamptz not null default now()
);
create unique index if not exists exercises_builtin_slug on public.exercises (slug) where owner_id is null;
create index if not exists exercises_owner on public.exercises (owner_id);

-- ---------------------------------------------------------------- plans
create table if not exists public.plans (
  id uuid primary key,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 120),
  description text not null default '',
  is_active boolean not null default false,
  archived_at timestamptz,
  template_key text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists plans_user on public.plans (user_id);

create table if not exists public.plan_days (
  id uuid primary key,
  plan_id uuid not null references public.plans (id) on delete cascade,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  weekday smallint not null check (weekday between 0 and 6),
  name text not null check (char_length(name) between 1 and 80),
  kind text not null check (kind in ('strength', 'cardio', 'activity', 'rest')),
  notes text not null default '',
  optional boolean not null default false,
  -- deferrable so two days can swap weekdays inside one batch upsert
  constraint plan_days_one_per_weekday unique (plan_id, weekday) deferrable initially deferred
);
create index if not exists plan_days_user on public.plan_days (user_id);

create table if not exists public.plan_exercises (
  id uuid primary key,
  plan_day_id uuid not null references public.plan_days (id) on delete cascade,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  exercise_id uuid not null references public.exercises (id) on delete restrict,
  position integer not null default 0,
  sets integer not null check (sets between 1 and 20),
  reps_min integer not null check (reps_min >= 0),
  reps_max integer not null,
  target_unit text not null default 'reps' check (target_unit in ('reps', 'seconds', 'minutes')),
  per_side boolean not null default false,
  rest_seconds integer not null default 60 check (rest_seconds between 0 and 900),
  notes text not null default '',
  check (reps_max >= reps_min)
);
create index if not exists plan_exercises_user on public.plan_exercises (user_id);
create index if not exists plan_exercises_day on public.plan_exercises (plan_day_id);

-- Per-date changes to the weekly schedule ("skip" a day, "add"/move a workout to a date).
create table if not exists public.scheduled_workouts (
  id uuid primary key,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  date date not null,
  kind text not null check (kind in ('skip', 'add')),
  plan_day_id uuid references public.plan_days (id) on delete cascade,
  moved_from date,
  note text not null default '',
  created_at timestamptz not null default now()
);
create index if not exists scheduled_workouts_user_date on public.scheduled_workouts (user_id, date);

-- ---------------------------------------------------------------- history
-- Sessions keep snapshots (title, plan_name, exercise names and targets) so they remain
-- readable after the plan is edited or deleted; plan links are set null, never cascaded.
create table if not exists public.workout_sessions (
  id uuid primary key,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  plan_id uuid references public.plans (id) on delete set null,
  plan_day_id uuid references public.plan_days (id) on delete set null,
  local_date date not null,
  title text not null,
  plan_name text,
  kind text not null check (kind in ('strength', 'cardio', 'activity')),
  status text not null check (status in ('in_progress', 'completed', 'partial', 'abandoned')),
  started_at timestamptz not null,
  ended_at timestamptz,
  duration_seconds integer check (duration_seconds >= 0),
  activity_type text,
  notes text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists workout_sessions_user_date on public.workout_sessions (user_id, local_date);

create table if not exists public.session_exercises (
  id uuid primary key,
  session_id uuid not null references public.workout_sessions (id) on delete cascade,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  exercise_id uuid references public.exercises (id) on delete set null,
  position integer not null default 0,
  name text not null,
  target_sets integer not null check (target_sets between 1 and 20),
  reps_min integer not null,
  reps_max integer not null,
  target_unit text not null default 'reps' check (target_unit in ('reps', 'seconds', 'minutes')),
  per_side boolean not null default false,
  rest_seconds integer not null default 60,
  uses_weight boolean not null default false,
  status text not null check (status in ('pending', 'active', 'completed', 'skipped')),
  started_at timestamptz,
  completed_at timestamptz,
  duration_seconds integer
);
create index if not exists session_exercises_user on public.session_exercises (user_id);
create index if not exists session_exercises_session on public.session_exercises (session_id);

create table if not exists public.completed_sets (
  id uuid primary key,
  session_exercise_id uuid not null references public.session_exercises (id) on delete cascade,
  session_id uuid not null references public.workout_sessions (id) on delete cascade,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  set_number integer not null check (set_number between 1 and 20),
  reps integer check (reps >= 0),
  weight numeric(7, 2) check (weight >= 0),
  weight_unit text check (weight_unit in ('kg', 'lb')),
  duration_seconds integer,
  completed_at timestamptz not null,
  -- a set is recorded only once
  constraint completed_sets_once unique (session_exercise_id, set_number)
);
create index if not exists completed_sets_user on public.completed_sets (user_id);

create table if not exists public.body_measurements (
  id uuid primary key,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  metric text not null,
  value numeric(8, 2) not null,
  unit text not null default '',
  measured_on date not null,
  created_at timestamptz not null default now()
);
create index if not exists body_measurements_user on public.body_measurements (user_id, metric, measured_on);

-- ---------------------------------------------------------------- housekeeping
create or replace function public.touch_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists workout_sessions_touch on public.workout_sessions;
create trigger workout_sessions_touch before update on public.workout_sessions
  for each row execute function public.touch_updated_at();
